// ==UserScript==
// @name         OLM GOD MODE v1.6 - Thiên Tai Tù Tội (VIP LOADER) [AES-256 ENCRYPTED]
// @namespace    http://tampermonkey.net/
// @version      1.9-enc
// @description  [AES-256-CBC] Hệ thống tự động hóa OLM — phiên bản mã hoá.
// @author       Thiên Tai Tù Tội
// @match        *://olm.vn/*
// @grant        GM_xmlhttpRequest
// @grant        GM_setValue
// @grant        GM_getValue
// @grant        GM_deleteValue
// @grant        unsafeWindow
// @connect      *
// @run-at       document-start
// ==/UserScript==
(async function _olmAes256Loader() {
    
    const _ENC = '';
    const _KEY = '81a7b1a2ebf19be7087cf715ccd5b8e47b9a1d753d7ab7f0a69d676598a1e215';

    
    function _h2b(h) {
        const b = new Uint8Array(h.length >> 1);
        for (let i = 0; i < b.length; i++) b[i] = parseInt(h.substr(i * 2, 2), 16);
        return b;
    }

    
    try {
        const raw = Uint8Array.from(atob(_ENC.replace(/[\s]/g, '')), c => c.charCodeAt(0));
        const iv  = raw.slice(0, 16);
        const ct  = raw.slice(16);
        const ck  = await crypto.subtle.importKey(
            'raw', _h2b(_KEY), { name: 'AES-CBC' }, false, ['decrypt']
        );
        const dec = await crypto.subtle.decrypt({ name: 'AES-CBC', iv }, ck, ct);

        
        const _code = new TextDecoder('utf-8').decode(dec);

        
        eval(_code);

    } catch (_e) {
        
        (function _showErr() {
            function show() {
                try {
                    const d = document.createElement('div');
                    d.style.cssText = 'position:fixed;bottom:12px;right:12px;background:rgba(239,83,80,.95);'
                        + 'color:#fff;padding:10px 14px;border-radius:8px;font-size:12px;'
                        + 'z-index:2147483647;max-width:300px;font-family:system-ui,sans-serif';
                    d.textContent = '[AES-ENC] Giải mã thất bại: ' + (_e && _e.message || _e);
                    (document.body || document.documentElement).appendChild(d);
                    setTimeout(() => d.remove(), 15000);
                } catch (_) {}
            }
            if (document.body) show(); else document.addEventListener('DOMContentLoaded', show);
        })();
    }
})();

